using System.Text.Json;
using Shop.Modules.Credit;
using Shop.SharedKernel;
using Xunit;
namespace Shop.Tests;
public sealed class CreditScheduleCalculatorTests
{
    private static CreditOrderScheduleSource Source(long payable=445988345,long down=128400000,CreditScheduleInstallmentSource[]? lines=null)=>new("QA","a".PadLeft(32,'a'),"AAAAAAAAAAE=","AwaitingPayment",DateTimeOffset.Parse("2020-01-01T00:00:00Z"),DateTimeOffset.Parse("2020-01-01T01:00:00Z"),new('b',32),new('c',32),new('d',32),new('E',64),"fa","Synthetic QA",payable,down,lines??[new(1,1,105858660),new(2,2,105858660),new(3,3,105858680)]);
    [Fact]public void UpfrontIncludesChargesOutsideChequesWithoutChangingThePlanDownPayment(){var x=CreditScheduleCalculator.Calculate(Source(),"Gregorian","2026-10-27");Assert.Equal("128400000",x.PlanDownPaymentRial);Assert.Equal("12345",x.ChargesOutsideChequesRial);Assert.Equal("128412345",x.UpfrontTotalRial);Assert.Equal("317576000",x.InstallmentsTotalRial);Assert.Equal("445988345",x.PayableTotalRial);Assert.Equal("Asia/Tehran",x.TimeZone);}
    [Theory][InlineData("2024-01-31","2024-02-29","2024-03-31")][InlineData("2025-01-31","2025-02-28","2025-03-31")]
    public void GregorianMonthEndsAreClampedFromOriginalAnchorWithoutCumulativeDrift(string anchor,string first,string second){var x=CreditScheduleCalculator.Calculate(Source(),"Gregorian",anchor);Assert.Equal(first,x.Lines[0].DueDate);Assert.Equal(second,x.Lines[1].DueDate);}
    [Fact]public void PersianCalendarMonthEndAndTheExplicitCalendarChoiceProduceTheirOwnCivilDates(){var x=CreditScheduleCalculator.Calculate(Source(),"Persian","2024-09-21");Assert.Equal("2024-10-21",x.Lines[0].DueDate);var persian=CreditScheduleCalculator.Calculate(Source(),"Persian","2026-10-27");var gregorian=CreditScheduleCalculator.Calculate(Source(),"Gregorian","2026-10-27");Assert.Equal("2026-11-26",persian.Lines[0].DueDate);Assert.Equal("2026-11-27",gregorian.Lines[0].DueDate);}
    [Theory][InlineData("2025-02-18","2025-03-20","2025-04-19")][InlineData("2026-02-19","2026-03-20","2026-04-19")]
    public void PersianEsfandLeapAndOrdinaryYearsClampOnlyTheAffectedMonth(string anchor,string first,string second){var x=CreditScheduleCalculator.Calculate(Source(),"Persian",anchor);Assert.Equal(first,x.Lines[0].DueDate);Assert.Equal(second,x.Lines[1].DueDate);}
    [Fact]public void FullyPrepaidQuoteRetainsAnEmptyChequeListAndAllChargesUpfront(){var x=CreditScheduleCalculator.Calculate(Source(112345,100000,[]),"Persian","2026-10-27");Assert.Empty(x.Lines);Assert.Equal("0",x.InstallmentsTotalRial);Assert.Equal("112345",x.UpfrontTotalRial);Assert.Equal("12345",x.ChargesOutsideChequesRial);}
    [Fact]public void ExactInt64AmountsStayDecimalStringsAndOverflowOrInconsistentFactsFail(){var x=CreditScheduleCalculator.Calculate(Source(9007199254740993,0,[new(1,1,9007199254740993)]),"Gregorian","2026-10-27");Assert.Equal("9007199254740993",x.Lines[0].AmountRial);Assert.Equal("0",x.UpfrontTotalRial);Assert.Throws<BusinessException>(()=>CreditScheduleCalculator.Calculate(Source(long.MaxValue,0,[new(1,1,long.MaxValue),new(2,2,1)]),"Gregorian","2026-10-27"));Assert.Throws<BusinessException>(()=>CreditScheduleCalculator.Calculate(Source(100,99,[new(1,1,2)]),"Gregorian","2026-10-27"));}
    [Fact]public void CivilAnchorUsesTehranCreationDayAndNeverAcceptsImplicitCalendarsOrInvalidDates(){var s=Source()with{CreatedAt=DateTimeOffset.Parse("2026-10-27T21:00:00Z"),ExpiresAt=DateTimeOffset.Parse("2026-10-27T22:00:00Z")};Assert.Throws<BusinessException>(()=>CreditScheduleCalculator.Calculate(s,"Gregorian","2026-10-27"));Assert.NotEmpty(CreditScheduleCalculator.Calculate(s,"Gregorian","2026-10-28").Lines);foreach(var bad in new[]{"2026-2-01","۲۰۲۶-۱۰-۲۷","2026-02-30","2026-10-27T00:00:00Z"})Assert.Throws<BusinessException>(()=>CreditScheduleCalculator.Calculate(Source(),"Gregorian",bad));Assert.Throws<BusinessException>(()=>CreditScheduleCalculator.Calculate(Source(),"","2026-10-27"));Assert.Throws<BusinessException>(()=>CreditScheduleCalculator.Calculate(Source(),"Gregorian","9999-12-31"));}
    [Fact]public void StrictScheduleInputCannotCarryClientAmountsDatesOrAuthorityAndRequiresReviewedPreview(){var input=new SaveCreditScheduleInput("AAAAAAAAAAE=",null,"Persian","2026-10-27",new('A',64),true);CreditScheduleRules.Validate(input);Assert.Throws<BusinessException>(()=>CreditScheduleRules.Validate(input with{Confirmed=false}));var json=new JsonSerializerOptions(JsonSerializerDefaults.Web);var raw=JsonSerializer.Serialize(input,json);foreach(var name in new[]{"amountRial","dueDates","ownerId","scopeId"})Assert.Throws<JsonException>(()=>JsonSerializer.Deserialize<SaveCreditScheduleInput>(raw[..^1]+",\""+name+"\":\"1\"}",json));}
}
